  /** The guest port this forward reaches. */
  remotePort(): number;
  /** The machine this forward reaches. */
  machineId(): string;
  /**
   * Stop forwarding and release the local port.
   *
   * Tunnels already open are dropped with it, so the port is genuinely
   * free when this returns. Calling it twice is not an error.
   */
